args.content:
#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
K3 技能交割安装器（yarn版）v1.0
----------------------------------------------------------------
依 skill-reinstall-ops 规程四条不可豁免：
  1. 预检先行（可写性）      2. 备份才可换（.bak）
  3. 装后必核（md5 逐文件）  4. 回写闭环（报告 install_report.json）

用法：
  python install_k3_skills.py --dry-run     # 只比对不落盘
  python install_k3_skills.py --apply       # 实际安装
"""
import os, sys, json, shutil, urllib.request, ssl, zipfile, hashlib, io, time

BASE = "https://huaweimianmoon.ok.kimi.link/"
INSTALL = r"C:\Users\欧阳宏俊\.workbuddy\skills"
WORK = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))  # .probe 的父级
STAGE = os.path.join(WORK, ".probe", "dist")
REPORT = os.path.join(WORK, ".probe", "install_report.json")

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE


def md5(b: bytes) -> str:
    return hashlib.md5(b).hexdigest()


def fix(name: str) -> str:
    """本机该站 zip 未置 UTF-8 标志位，中文名须 cp437→utf8 反转（K3 交接班实证）。"""
    try:
        return name.encode("cp437").decode("utf-8")
    except Exception:
        return name


def http_get(url: str, tries: int = 3) -> bytes:
    last = None
    for i in range(tries):
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(req, timeout=60, context=ctx) as r:
                return r.read()
        except Exception as e:
            last = e
            time.sleep(1.2 * (i + 1))
    raise RuntimeError(f"下载失败 {url}: {last}")


def read_skill_zip(data: bytes):
    """返回 {fix后的相对路径: bytes}"""
    out = {}
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        for info in z.infolist():
            if info.is_dir():
                continue
            out[fix(info.filename)] = z.read(info)
    return out


def local_files(skill_dir: str):
    """返回 {相对路径: md5}"""
    m = {}
    root = os.path.join(INSTALL, skill_dir)
    for dirpath, _, files in os.walk(root):
        for f in files:
            p = os.path.join(dirpath, f)
            rel = os.path.relpath(p, root).replace("\\", "/")
            try:
                m[rel] = md5(open(p, "rb").read())
            except Exception:
                pass
    return m


def main():
    apply_mode = "--apply" in sys.argv
    print("=== K3 技能交割安装器 v1.0 ===")
    print(f"模式: {'APPLY（实际安装）' if apply_mode else 'DRY-RUN（只比对不落盘）'}")
    print(f"安装位: {INSTALL}")

    # --- 1. 预检可写性 ---
    probe = os.path.join(INSTALL, ".__write_test")
    try:
        open(probe, "w").close()
        os.remove(probe)
        print("[预检] 安装位可写 ✔")
    except Exception as e:
        print(f"[预检] 安装位不可写 ✘ — {e}。按规程如实停止，不假装成功。")
        return 2

    os.makedirs(STAGE, exist_ok=True)

    # --- 2. 取交割页清单 ---
    html = http_get(BASE).decode("utf-8", "ignore")
    skills = sorted(set(
        s.split('"')[0] for s in
        [x[len('href="'):] for x in html.split('href="')[1:]]
        if s.split('"')[0].endswith(".skill")
    ))
    print(f"[清单] 交割页 .skill 共 {len(skills)} 件")

    news, updates, sames, fails = [], [], [], []

    for i, fn in enumerate(skills, 1):
        name = fn[:-len(".skill")]
        try:
            cache = os.path.join(STAGE, fn)
            data = open(cache, "rb").read() if os.path.exists(cache) else http_get(BASE + fn)
            if not os.path.exists(cache):
                open(cache, "wb").write(data)

            pkg = read_skill_zip(data)
            # 包内应以 <name>/ 为根；兼容无前缀根的情形
            if not any(k.startswith(name + "/") for k in pkg):
                pkg = {(name + "/" + k): v for k, v in pkg.items()}

            remote = {k.split("/", 1)[1]: md5(v) for k, v in pkg.items() if "/" in k}

            exists = os.path.isdir(os.path.join(INSTALL, name))
            if not exists:
                news.append((name, pkg))
                tag = "新增"
            else:
                loc = local_files(name)
                diff = [k for k, v in remote.items() if loc.get(k) != v]
                if diff:
                    updates.append((name, pkg, diff))
                    tag = f"更新({len(diff)}文件)"
                else:
                    sames.append(name)
                    tag = "一致"
            print(f"  [{i:3d}/{len(skills)}] {name:<34} {tag}")
        except Exception as e:
            fails.append((name, str(e)))
            print(f"  [{i:3d}/{len(skills)}] {name:<34} 失败: {str(e)[:60]}")

    print(f"\n[比对] 新增 {len(news)} / 需更新 {len(updates)} / 已一致 {len(sames)} / 失败 {len(fails)}")

    if not apply_mode:
        print("\n[DRY-RUN] 未做任何写入。加 --apply 执行安装。")
        if news:
            print("  将新增：")
            for n, _ in news:
                print("    +", n)
        if updates:
            print("  将更新：")
            for n, _, d in updates:
                print("    ~", n, d)
        json.dump({"news": [n for n, _ in news],
                   "updates": [[n, d] for n, _, d in updates],
                   "sames": sames, "fails": fails},
                  open(REPORT, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
        return 0

    # --- 3. 安装：备份 → 换位 ---
    installed, tainted = [], []
    ts = time.strftime("%Y%m%d-%H%M%S")

    def place(name, pkg):
        dst = os.path.join(INSTALL, name)
        new = os.path.join(INSTALL, f"{name}.new")
        bak = os.path.join(INSTALL, f"{name}.bak-{ts}")
        try:
            if os.path.isdir(new):
                shutil.rmtree(new)
            for rel, content in pkg.items():
                parts = rel.split("/")
                if parts[0] == name and len(parts) > 1:
                    rel = "/".join(parts[1:])
                t = os.path.join(new, rel)
                os.makedirs(os.path.dirname(t), exist_ok=True)
                open(t, "wb").write(content)
            if os.path.isdir(dst):
                shutil.move(dst, bak)          # 先备份
            shutil.move(new, dst)
            # 核验
            loc = local_files(name)
            want = {k.split("/", 1)[1]: md5(v) for k, v in pkg.items() if "/" in k}
            bad = [k for k, v in want.items() if loc.get(k) != v]
            return (len(want), bad)
        except Exception as e:
            if os.path.isdir(new):
                shutil.rmtree(new, ignore_errors=True)
            raise e

    for n, pkg in news:
        try:
            cnt, bad = place(n, pkg)
            installed.append((n, "新增", cnt, bad))
            print(f"  [安装] + {n:<34} {cnt} 文件 {'✔' if not bad else '✘ ' + str(bad[:3])}")
        except Exception as e:
            tainted.append((n, str(e)))
            print(f"  [安装] + {n:<34} 失败: {e}")

    for n, pkg, _d in updates:
        try:
            cnt, bad = place(n, pkg)
            installed.append((n, "更新", cnt, bad))
            print(f"  [安装] ~ {n:<34} {cnt} 文件 {'✔' if not bad else '✘ ' + str(bad[:3])}")
        except Exception as e:
            tainted.append((n, str(e)))
            print(f"  [安装] ~ {n:<34} 失败: {e}")

    total = len(os.listdir(INSTALL))
    print(f"\n[核验] 安装位现共存 {total} 项（含 .bak 备份）")
    print(f"[结果] 成功 {len(installed)} / 失败 {len(tainted)}")

    json.dump({"mode": "apply", "ts": ts,
               "installed": [[n, k, c, b] for n, k, c, b in installed],
               "failed": tainted, "sames": sames,
               "bak_suffix": f".bak-{ts}"},
              open(REPORT, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
    print(f"[回写] 报告 → {REPORT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

