_BAD = '<>:"|?*'
_SANITIZED = []


def sanitize_path(rel: str) -> str:
    parts = []
    for seg in rel.split("/"):
        if any(c in seg for c in _BAD):
            fixed = "".join("_" if c in _BAD else c for c in seg)
            _SANITIZED.append((seg, fixed))
            seg = fixed
        parts.append(seg.rstrip(" ."))
    return "/".join(parts)

