// ===== Supabase REST 客户端 =====
class SupabaseBus {
  constructor(url, key) {
    this.base = `${url}/rest/v1`;
    this.url = url;
    this.key = key;
    this.headers = {
      'apikey': key,
      'Authorization': `Bearer ${key}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    };
  }

  async insert(table, row) {
    const resp = await fetch(`${this.base}/${table}`, {
      method: 'POST',
      headers: this.headers,
      body: JSON.stringify(row),
    });
    if (!resp.ok) {
      const text = await resp.text();
      throw new Error(`INSERT ${table} HTTP ${resp.status}: ${text}`);
    }
    return resp.json();
  }

  async select(table, filters = {}, limit = 100, afterId = 0) {
    let query = `${this.base}/${table}?id=gt.${afterId}&limit=${limit}&order=id.asc`;
    for (const [k, v] of Object.entries(filters)) {
      query += `&${k}=eq.${encodeURIComponent(v)}`;
    }
    const resp = await fetch(query, {
      method: 'GET',
      headers: this.headers,
    });
    if (!resp.ok) {
      const text = await resp.text();
      throw new Error(`SELECT ${table} HTTP ${resp.status}: ${text}`);
    }
    return resp.json();
  }

  async update(table, id, patch) {
    const resp = await fetch(`${this.base}/${table}?id=eq.${id}`, {
      method: 'PATCH',
      headers: { ...this.headers, 'Prefer': 'return=representation' },
      body: JSON.stringify(patch),
    });
    if (!resp.ok) {
      const text = await resp.text();
      throw new Error(`UPDATE ${table} HTTP ${resp.status}: ${text}`);
    }
    return resp.json();
  }
}

