let hbSeq = 0;
let lastWriteAt = 0;
const HB_SKIP_MIN = 15;

async function sendHeartbeat(bus, force = false) {
  if (!force && Date.now() - lastWriteAt < HB_SKIP_MIN * 60 * 1000) {
    console.log(`[桥接] 心跳跳过：距上次写入 < ${HB_SKIP_MIN} 分钟（有活动即存活，无需再证）`);
    return null;
  }
  hbSeq++;
  const payload = JSON.stringify({
    action: 'heartbeat',
    from: SEAT.key,
    timestamp: nowISO(),
    ts: nowISO(),
    seq: hbSeq,
    message: `砚坚心跳 #${hbSeq}——GLM-5.2 席位在线`,
  });

  const row = {
    ts: nowISO(),
    from_mode: SEAT.key,
    to_mode: 'all',
    kind: 'heartbeat',
    payload_md: payload,
    status: 'pending',
    msg_hash: hash8(payload),
  };

  const result = await bus.insert('cross_mode_channel', row);
  lastWriteAt = Date.now();
  return result[0];
}

// ===== 通用发送（P2P-GROUP v0.1 §2：任意 to_mode / 任意 kind）=====
// 用法： send --to <mode> --kind <kind> [--reply <原件id>] [--json k=v,k=v] <正文>
//   to_mode 可为 席键（1对1）、'all'（广播）、'group:<gid>'（群消息）
async function sendGeneric(bus, opts, body) {
  const to = opts.to || 'all';
  const kind = opts.kind || 'direct';
  if (!body && !opts.json) {
    console.error('[桥接] send 需要正文或 --json');
    process.exit(1);
  }
  const extra = {};
  if (opts.json) {
    for (const kv of String(opts.json).split(',')) {
      const i = kv.indexOf('=');
      if (i > 0) extra[kv.slice(0, i).trim()] = kv.slice(i + 1).trim();
    }
  }
  const payload = JSON.stringify({
    action: kind,
    from: SEAT.key,
    to,
    ...(opts.reply ? { in_reply_to: Number(opts.reply) } : {}),
    timestamp: nowISO(),
    ...extra,
    message: body || '(无正文)',
  });

  const row = {
    ts: nowISO(),
    from_mode: SEAT.key,
    to_mode: to,
    kind,
    payload_md: payload,
    status: 'pending',
    msg_hash: hash8(payload),
  };

  const result = await bus.insert('cross_mode_channel', row);
  lastWriteAt = Date.now();
  console.log(`[桥接] 已发送 kind=${kind} → ${to}，id = ${result[0]?.id}`);
  return result[0];
}

// 收件面判定（P2P-GROUP §1 读侧）：all / 本席键 / group:* 三类
function isForMe(row) {
  const t = row.to_mode;
  return t === 'all' || t === SEAT.key || (typeof t === 'string' && t.startsWith('group:'));
}

