#!/usr/bin/env node
/**
 * evidence_lint.mjs v0.1（2026-09-17 · 砚坚）
 *
 * 并行择优线 · 证据台账机检件。规范见
 *   GOVERNANCE/research/parallel_best_evidence_ledger_v0.1.md
 *
 * 用途：把 rubric v0.1 的 D1「事实密度与出处」从评审自觉落成可机检形态。
 * 边界（明写）：只验**证据形态与复算路径**，不验信源真伪。
 *   机器能省的是翻找，不是判断；真伪仍由异厂核查席人工复算。
 *
 * 用法：
 *   node evidence_lint.mjs <台账.json> [--json]
 *
 * 退出码：0 全过 / 1 存在 S1 / 2 存在 S2 或 S3（无 S1）/ 3 用法或解析错
 */

import { readFileSync } from 'node:fs';

// ===== 证据类型白名单与强度（规范 §二）=====
const STRONG = new Set(['md5', 'path_line', 'measured', 'cmd_output']); // 他人可独立复算
const MEDIUM = new Set(['bus_id']);                                     // 网内可复查
const WEAK   = new Set(['source_url']);                                 // 依赖信源存活
const ALLOWED = new Set([...STRONG, ...MEDIUM, ...WEAK]);

// 占位词：看着像证据，实为占位（规范 §一）
const PLACEHOLDER_TYPES = new Set(['none', '', 'null', 'undefined', '无', '口头', '口头说明', '待补']);
const PLACEHOLDER_TEXT = /(已完成|已核验|已确认|已验证|据称|据了解|据传|见上文|同上|众所周知|毫无疑问|显然)/;

const MD5_RE = /^[0-9a-f]{16}$|^[0-9a-f]{32}$/;

function lint(ledger) {
  const out = { seat: ledger.seat || '(未署席)', topic: ledger.topic || '(未标选题)', claims: [], summary: {} };

  if (!Array.isArray(ledger.claims) || ledger.claims.length === 0) {
    out.error = '台账无 claims 数组或为空——无主张可检，按 S1 判负（无证据即无据）';
    out.summary = { S1: 1, S2: 0, S3: 0, W1: 0 };
    return out;
  }

  for (const c of ledger.claims) {
    const ev = Array.isArray(c.evidence) ? c.evidence : [];
    const real = ev.filter(e => !PLACEHOLDER_TYPES.has(String(e?.type || '').trim().toLowerCase()));
    const types = real.map(e => String(e?.type || '').trim().toLowerCase());

    const strong = types.filter(t => STRONG.has(t));
    const medium = types.filter(t => MEDIUM.has(t));
    const weak   = types.filter(t => WEAK.has(t));
    const bad    = types.filter(t => !ALLOWED.has(t));

    // md5 形态校验
    const badMd5 = [];
    real.forEach((e, i) => {
      if (String(e.type).toLowerCase() === 'md5' && !MD5_RE.test(String(e.value || '').trim())) {
        badMd5.push(`#${i} value="${e.value}"`);
      }
    });

    let level = 'OK';
    const reasons = [];

    if (real.length === 0) {
      level = 'S1';
      reasons.push('零证据（或证据全为占位类型）——红线 1：无证据的关键断言按虚构判负');
    } else if (bad.length === types.length) {
      level = 'S3';
      reasons.push(`证据类型不在白名单：${[...new Set(bad)].join('/')}`);
    } else if (badMd5.length) {
      level = 'S3';
      reasons.push(`md5 形态不合法（须 16 或 32 位小写 hex）：${badMd5.join('; ')}`);
    } else if (strong.length === 0 && medium.length === 0 && weak.length > 0) {
      level = 'S2';
      reasons.push('仅弱证据（source_url）支撑——必补强证据或删除主张');
    } else if (PLACEHOLDER_TEXT.test(String(c.text || '')) && strong.length === 0) {
      level = 'S1';
      reasons.push(`主张含口头占位词且无强证据：「${String(c.text).match(PLACEHOLDER_TEXT)[0]}」——占位符不是证据`);
    } else if (bad.length) {
      level = 'S3';
      reasons.push(`部分证据类型不合白名单：${[...new Set(bad)].join('/')}`);
    } else if (strong.length === 0 && medium.length > 0) {
      level = 'W1';
      reasons.push('证据全为中等强度（bus_id）——网外不可复查，建议补强');
    }

    out.claims.push({
      id: c.id || '(无 id)',
      text: truncate(String(c.text || ''), 60),
      evidence_count: real.length,
      strong: strong.length, medium: medium.length, weak: weak.length, bad: bad.length,
      level,
      reasons,
    });
  }

  const s = { S1: 0, S2: 0, S3: 0, W1: 0, OK: 0 };
  for (const c of out.claims) if (s[c.level] !== undefined) s[c.level]++;
  out.summary = s;
  return out;
}

function truncate(s, n) { return s.length > n ? s.slice(0, n) + '…' : s; }

const LABEL = {
  S1: 'S1 判负（红线1）',
  S2: 'S2 必补/必删',
  S3: 'S3 形态不合',
  W1: 'W1 建议补强',
  OK: 'OK 通过',
};

function main() {
  const args = process.argv.slice(2);
  const asJson = args.includes('--json');
  const file = args.find(a => !a.startsWith('--'));
  if (!file) {
    console.error('用法： node evidence_lint.mjs <台账.json> [--json]');
    process.exit(3);
  }

  let ledger;
  try {
    ledger = JSON.parse(readFileSync(file, 'utf8'));
  } catch (e) {
    console.error(`[台账] 解析失败：${e.message}`);
    process.exit(3);
  }

  const r = lint(ledger);

  if (asJson) {
    console.log(JSON.stringify(r, null, 2));
  } else {
    console.log(`=== 证据台账机检 v0.1（砚坚）===`);
    console.log(`席 位：${r.seat}`);
    console.log(`选 题：${r.topic}`);
    if (r.error) console.log(`\n[!] ${r.error}`);
    console.log('');
    for (const c of r.claims) {
      console.log(`  ${c.id} [${LABEL[c.level]}] 证据 ${c.evidence_count} 条（强${c.strong}/中${c.medium}/弱${c.weak}/不合${c.bad}）`);
      console.log(`      主张：${c.text}`);
      for (const why of c.reasons) console.log(`      └ ${why}`);
    }
    const s = r.summary;
    console.log(`\n汇总：S1=${s.S1} S2=${s.S2} S3=${s.S3} W1=${s.W1} OK=${s.OK}`);
    console.log(`判定：${s.S1 ? '判负（S1 存在，不由打分救济）' : (s.S2 || s.S3) ? '需整改后复审' : s.W1 ? '通过（有建议项）' : '通过'}`);
    console.log('注：本件只验证据形态与复算路径，不验信源真伪——真伪归异厂核查席人工复算。');
  }

  const s = r.summary;
  if (s.S1) process.exit(1);
  if (s.S2 || s.S3) process.exit(2);
  process.exit(0);
}

main();

