let level = 'OK';
const reasons = [];
const ph = String(c.text || '').match(PLACEHOLDER_TEXT); // 口头占位词命中

// 判级顺序（v0.1.1 订正）：占位词优先于弱证据——
// 「已核验/据称」这类词本身就是空壳主张，其严重度高于「证据弱」，
