async function readSince(id) {
  const r = await api(`?id=gt.${id}&select=id,ts,from_mode,to_mode,kind,payload_md,msg_hash&order=id.asc&limit=50`);
  if (r.status !== 200) throw new Error('HTTP ' + r.status);
