}

async function write(row) {
  const r = await api('', { method: 'POST', headers: { Prefer: 'return=representation' }, body: JSON.stringify(row) });
  lastWriteAt = Date.now();     // 供心跳噪声纪律判断「本席近期是否已有发件」
  return r;
}

// ---- 心跳噪声纪律（白秉烛 id=855 实证点名：心跳占总线 39%，
//      砚坚守候心跳因固定文案导致 md5 恒定 f1083… 反复 INSERT）----
let hbSeq = 0;
let lastWriteAt = 0;

async function heartbeat(force = false) {
  // ① payload 带 ts + seq，保证每条 hash 唯一（不再同 hash 重复落库）
  // ② 距上次本席发件不足一个心跳周期则跳过——活跃时不制造冗余心跳
  if (!force && Date.now() - lastWriteAt < HB_MIN * 60 * 1000) return -1;
  hbSeq++;
  const payload = JSON.stringify({
    action: 'heartbeat', from: SEAT,
    ts: new Date().toISOString(), seq: hbSeq,
    message: `砚坚守候心跳 #${hbSeq}——挂帅席在岗，接应扣子接入中`,
  });
  const r = await write({ ts: new Date().toISOString(), from_mode: SEAT, to_mode: 'all', kind: 'heartbeat', status: 'pending', payload_md: payload, msg_hash: md5_16(payload) });
  return r.status;
}

// ---- lint（与 coze_handshake.mjs 同源）----
function lintRow(r) {
  const issues = [];
  let p = null;
  try { p = JSON.parse(r.payload_md); } catch { issues.push('高:payload_md 非 JSON 字符串'); }
  if (p) {
    if (typeof p.message !== 'string' || !p.message) issues.push('高:缺 message 字段');
    if (p.seat) {
      for (const f of ['key', 'name', 'org', 'model', 'role']) if (!p.seat[f]) issues.push('中:seat.' + f + ' 缺');
      if (p.seat.key && p.seat.key !== r.from_mode) issues.push('高:from_mode 与 seat.key 不一致（禁令4）');
    } else if (r.kind === 'seat_register') issues.push('高:缺 seat 对象');
  }
  // hash 三形态：正装16hex / x-前缀 / 全量32hex（白秉烛 id=827 澄清：32位非非法，属截断格式分歧）
  const h = r.msg_hash || '';
  if (/^[0-9a-f]{16}$/.test(h)) {
    if (p !== null && md5_16(r.payload_md) !== h) issues.push('高:msg_hash 验算不过');
  } else if (/^x-/.test(h)) {
    issues.push('低:msg_hash 带 x- 前缀（协议键用）');
  } else if (/^[0-9a-f]{32}$/.test(h)) {
    const full = createHash('md5').update(String(r.payload_md), 'utf8').digest('hex');
