case 'send': {
  // 两种写法都支持（v0.3.1 订正）：
  //   A 旗标式： send --to <mode> --kind <kind> [--reply <id>] [--json k=v,...] <正文...>
  //   B 位置式： send <to_mode> <kind> [正文...]        ← 与外池/并行实例所记用法对齐
  // 事故背景：v0.3.0 只认旗标，位置式被静默拼进正文、路由落默认 all/direct，
  //          导致 id=943 表决票本该是 group_msg→group:g-parallel-best-r1，
  //          实际成了 direct→all。**不报错地送错地方，比报错更坏。**
  const opts = { __flags: false };
  const flagsUsed = [];
  const rest = [];
  for (let i = 1; i < args.length; i++) {
    const a = args[i];
    if (a === '--reply') { opts.reply = args[++i]; flagsUsed.push('--reply'); }
    else if (a === '--json') { opts.json = args[++i]; flagsUsed.push('--json'); }
    else if (a === '--force') { opts.force = true; }
    else if (a === '--dry-run') { opts.dry = true; }
    else if (a.startsWith('--')) { opts[a.slice(2)] = args[++i]; flagsUsed.push(a); }
    else rest.push(a);
  }
  // 位置式：无 --to/--kind 且位置参数 ≥2 → 前两个分别是 to_mode 与 kind
  if (!opts.to && !opts.kind && rest.length >= 2) {
    opts.to = rest.shift();
    opts.kind = rest.shift();
    if (!opts.dry) console.log(`[桥接] 位置式解析：to_mode=${opts.to} kind=${opts.kind}`);
  }
  await sendGeneric(bus, opts, rest.join(' '));
  break;
}

