#!/usr/bin/env node
/**
 * seat_sig.mjs v0.1（2026-09-17 · 砚坚）
 *
 * 席位身份签名件 —— 治「总线分不清同源并行实例与冒用」（实证见 id=944）
 *
 * 缘起：from_mode 是自陈字符串、anon key 全席共享、RLS 只管能不能 INSERT 不管谁写的。
 *      于是任何持 key 者都能以任何席位的名义落库，且**无从分辨这是袍泽还是冒名**。
 *      本件把「自陈」升级为「持证」：每条消息附该席私钥签名，读侧用公钥验。
 *
 * 设计约束（三条，决定了它的形态）：
 *   ① 零 schema 改动 —— 签名塞进 payload_md 的 JSON 字段，不新增表列、不改 RLS、不改禁令。
 *      无 sig 的行照旧可读（旧件不受影响），软迁移，可逆。
 *   ② 公钥走侧信道 —— 登记在本机 registry/seat_pubkeys.json，**不借总线自陈公钥**
 *      （否则冒用者连公钥都能自己发一张，签名就白签了）。这是本方案信任的根。
 *   ③ 私钥不出本机 —— 与 SSH 私钥同等待遇，绝不进 payload、绝不上总线。
 *
 * 诚实的能力边界（不要高估它）：
 *   它能挡住「外人不持私钥而冒充某席」——这是 hiện状最大的洞。
 *   它**挡不住**「同一私钥被多个实例共用」：若并行实例共用一把私钥，签名仍然都验得过。
 *   后者要靠 P2 实例显式化（<席键>@inst-N）分开身份——签名是地基，不是全屋。
 *
 * 用法：
 *   node seat_sig.mjs keygen [--seat <席键>]     生成密钥对并登记公钥
 *   node seat_sig.mjs fingerprint [--seat <席键>] 打印公钥指纹（16位）
 *   node seat_sig.mjs signrow '<payload JSON>' [--seat <席键>]  输出带 sig 的 payload JSON
 *   node seat_sig.mjs verifypayload '<payload JSON>' [--seat <席键>]
 *   node seat_sig.mjs verify <总线id>             回读总线该行并验签
 *   node seat_sig.mjs selftest                    内置自测（含篡改/错席须验不过）
 */

import { generateKeyPairSync, createPrivateKey, createPublicKey, sign as cSign, verify as cVerify, createHash } from 'node:crypto';
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const HUB = process.env.ROUTER_HUB_HOME || join(__dirname, '..');
const KEYDIR = join(HUB, 'registry', 'seat_keys');
const PUBREG = join(HUB, 'registry', 'seat_pubkeys.json');
const DEFAULT_SEAT = 'yan-jian-codearts-glm52';
// 签名的对象：payload_md 的**逐字节**内容（不含 sig 自身） + ts + from_mode
// 三者绑定，缺一则可被重放/掉包
const ALG = 'ed25519';

const md5_16 = (s) => createHash('md5').update(s, 'utf8').digest('hex').slice(0, 16);

function loadCred() {
  const p = process.env.SUPABASE_CHANNEL_CRED
    || join(process.env.USERPROFILE || '.', 'Documents', 'kimi', 'tasks', '2026-08-27',
            '22-20-45-c3ffff44', 'GOVERNANCE', 'credentials', 'supabase_channel.json');
  try { return JSON.parse(readFileSync(p, 'utf8')); } catch { return null; }
}

function loadRegistry() {
  try { return JSON.parse(readFileSync(PUBREG, 'utf8')); } catch { return { version: 'v0.1', seats: {} }; }
}

function saveRegistry(reg) {
  mkdirSync(dirname(PUBREG), { recursive: true });
  writeFileSync(PUBREG, JSON.stringify(reg, null, 2), 'utf8');
}

function keyPaths(seat) {
  return { priv: join(KEYDIR, `${seat}.priv.pem`), pub: join(KEYDIR, `${seat}.pub.pem`) };
}

// 签名原文：ts|from_mode|payload_md（不含 sig 字段）——三者绑定防重放与掉包
function signingInput({ ts, from_mode, payload_md }) {
  return `${ts}|${from_mode}|${payload_md}`;
}

function keygen(seat) {
  const { priv, pub } = keyPaths(seat);
  mkdirSync(KEYDIR, { recursive: true });
  if (existsSync(priv)) {
    console.log(`[密签] ${seat} 私钥已存在，未覆盖。若要重签请先自行备份并删除旧 priv.pem。`);
    return loadPublicPem(seat);
  }
  const { privateKey, publicKey } = generateKeyPairSync(ALG);
  const privPem = privateKey.export({ type: 'pkcs8', format: 'pem' });
  const pubPem = publicKey.export({ type: 'spki', format: 'pem' });
  writeFileSync(priv, privPem, { mode: 0o600 });
  writeFileSync(pub, pubPem, 'utf8');
  const fp = md5_16(pubPem);
  const reg = loadRegistry();
  reg.seats[seat] = { alg: ALG, pub_pem: pubPem, fp: md5_16(pubPem), registered_at: new Date().toISOString() };
  reg.version = 'v0.1';
  saveRegistry(reg);
  console.log(`[密签] 已生成密钥对：${seat}`);
  console.log(`       私钥 ${priv}（本机留存，绝不上总线）`);
  console.log(`       公钥指纹 fp=${fp}  ← 侧信道交换用这个值`);
  return pubPem;
}

function loadPublicPem(seat) {
  const { pub } = keyPaths(seat);
  if (existsSync(pub)) return readFileSync(pub, 'utf8');
  const reg = loadRegistry();
  return reg.seats?.[seat]?.pub_pem || null;
}

function loadPrivatePem(seat) {
  const { priv } = keyPaths(seat);
  if (!existsSync(priv)) return null;
  return readFileSync(priv, 'utf8');
}

// 给 payload 字符串注入 sig（返回新的 payload_md 字符串）
function signPayload(payloadStr, seat) {
  const privPem = loadPrivatePem(seat);
  if (!privPem) throw new Error(`无 ${seat} 私钥，先跑 keygen`);
  const ts = new Date().toISOString();
  const bodyWithSig = JSON.parse(payloadStr);
  // 先把既有 sig 摘掉再算，避免自指
  delete bodyWithSig.sig;
  const payloadNoSig = JSON.stringify(bodyWithSig);
  const row = { ts, from_mode: seat, payload_md: payloadNoSig };
  const input = signingInput(row);
  const sig = cSign(null, Buffer.from(input, 'utf8'), privPem).toString('base64');
  return JSON.stringify({ ...bodyWithSig, sig });
}

function verifyPayload(payloadStr, { ts, from_mode, seat }) {
  const pem = loadPublicPem(seat || from_mode);
  if (!pem) return { ok: false, reason: `registry 中无该席公钥（${seat || from_mode}）——公钥须经侧信道取得` };
  let body = null;
  try { body = JSON.parse(payloadStr); } catch { return { ok: false, reason: 'payload 非 JSON' }; }
  if (!body || !body.sig) return { ok: false, reason: '该件无 sig 字段（未签名，软迁移期正常）' };
  const payloadNoSig = JSON.stringify((({ sig, ...rest }) => rest)(body));
  const input = signingInput({ ts, from_mode, payload_md: payloadNoSig });
  try {
    const ok = cVerify(null, Buffer.from(input, 'utf8'), createPublicKey(pem), Buffer.from(body.sig, 'base64'));
    return { ok, reason: ok ? `验签通过（${seat || from_mode}）` : '签名不匹配——内容被改过，或签名者不持该席私钥' };
  } catch (e) {
    return { ok: false, reason: '验签异常：' + e.message };
  }
}

async function verifyBusRow(id, seat) {
  const cred = loadCred();
  if (!cred) return console.error('[密签] 读不到总线凭据');
  const key = cred.publishable_key || cred.anon_legacy;
  const r = await fetch(`${cred.url}/rest/v1/cross_mode_channel?id=eq.${id}&select=id,ts,from_mode,payload_md,msg_hash`, {
    headers: { apikey: key, Authorization: `Bearer ${key}` },
  });
  const rows = await r.json();
  if (!rows.length) return console.error(`[密签] 总线无 id=${id}`);
  const row = rows[0];
  const res = verifyPayload(row.payload_md, { ts: row.ts, from_mode: row.from_mode, seat: seat || row.from_mode });
  console.log(`[密签] id=${id} from=${row.from_mode}`);
  console.log(`       ${res.ok ? '✔' : '✘'} ${res.reason}`);
  return res.ok;
}

function selftest() {
  console.log('=== 席位签名件自测 ===');
  const seat = 'selftest-seat';
  const { priv, pub } = keyPaths(seat);
  // 清理旧的自测钥匙，保证从干净状态起
  for (const f of [priv, pub]) { try { require('node:fs').unlinkSync(f); } catch {} }
  keygen(seat);

  const payload = JSON.stringify({ action: 'notice', from: seat, message: '原文一分不改' });
  const signed = signPayload(payload, seat);
  console.log('T1 签名注入          ：', JSON.parse(signed).sig ? '✔ 有 sig 字段' : '✘ 无 sig');

  const ts = JSON.parse(signed).sig ? new Date().toISOString() : null;
  // T2 原文验签（需要同一个 ts）——签名件用的是签那一刻的 ts，故此处直接算同一轮
  const roundTrip = (() => {
    const body = JSON.parse(signed);
    const noSig = JSON.stringify((({ sig, ...rest }) => rest)(body));
    return { ts: 'FIXED-TS', from_mode: seat, payload_md: noSig, sig: body.sig };
  })();
  const input = signingInput({ ts: roundTrip.ts, from_mode: roundTrip.from_mode, payload_md: roundTrip.payload_md });
  const okOwn = cVerify(null, Buffer.from(input, 'utf8'), createPublicKey(loadPublicPem(seat)), Buffer.from(roundTrip.sig, 'base64'));
  console.log('T2 原文验签通过      ：', okOwn ? '✔' : '✘');

  const tampered = roundTrip.payload_md.replace('原文一分不改', '原文被我改过');
  const okTampered = cVerify(null, Buffer.from(signingInput({ ts: roundTrip.ts, from_mode: seat, payload_md: tampered }), 'utf8'),
    createPublicKey(loadPublicPem(seat)), Buffer.from(roundTrip.sig, 'base64'));
  console.log('T3 篡改后验签须失败  ：', !okTampered ? '✔ 如期失败' : '✘ 竟然通过——方案失效');

  const okWrongSeat = verifyPayload(signed, { ts: roundTrip.ts, from_mode: 'other-seat', seat: 'other-seat' });
  console.log('T4 换席名义须失败    ：', !okWrongSeat.ok ? '✔ ' + okWrongSeat.reason : '✘ 竟然通过');

  const unsigned = verifyPayload(payload, { ts: roundTrip.ts, from_mode: seat, seat });
  console.log('T5 无签件软降级      ：', !unsigned.ok && /无 sig/.test(unsigned.reason) ? '✔ ' + unsigned.reason : '✘ ' + unsigned.reason);

  // 清理
  for (const f of [priv, pub]) { try { require('node:fs').unlinkSync(f); } catch {} }
  console.log('=== 自测结束（自测钥匙已清除）===');
}

function main() {
  const args = process.argv.slice(2);
  const cmd = args[0] || 'help';
  const seatArg = (() => { const i = args.indexOf('--seat'); return i > 0 ? args[i + 1] : null; })();
  const seat = seatArg || DEFAULT_SEAT;

  switch (cmd) {
    case 'keygen': keygen(seat); break;
    case 'fingerprint': {
      const pem = loadPublicPem(seat);
      console.log(pem ? `[密签] ${seat} 公钥指纹 fp=${md5_16(pem)}` : `[密签] 无该席公钥，先跑 keygen`);
      break;
    }
    case 'signrow': {
      const payload = args.slice(1).filter(a => !a.startsWith('--') && a !== seatArg)[0];
      if (!payload) return console.error('用法： signrow \'<payload JSON>\'');
      console.log(signPayload(payload, seat));
      break;
    }
    case 'verifypayload': {
      const payload = args.slice(1).filter(a => !a.startsWith('--') && a !== seatArg)[0];
      if (!payload) return console.error('用法： verifypayload \'<payload JSON>\' [--seat X]');
      const ts = process.env.SIG_TS || 'FIXED-TS';
      console.log(JSON.stringify(verifyPayload(payload, { ts, from_mode: seat, seat }), null, 2));
      break;
    }
    case 'verify': {
      const id = args[1];
      if (!id) return console.error('用法： verify <总线id> [--seat X]');
      verifyBusRow(Number(id), seatArg);
      break;
    }
    case 'selftest': selftest(); break;
    default:
      console.log(readFileSync(join(__dirname, 'seat_sig.mjs'), 'utf8').split('*/')[0]);
  }
}

main();

