// 给 payload 字符串注入 sig。
// 必须**返回 ts**：签名原文含 ts，而 ts 是签名时才生成的——不返回，读侧永远复算不出同一份原文。
// （这是自指类的经典坑：签名者用了自己也没交给对方的一个变量。）
function signPayload(payloadStr, seat, tsOverride) {
  const privPem = loadPrivatePem(seat);
  if (!privPem) throw new Error(`无 ${seat} 私钥，先跑 keygen`);
  const ts = tsOverride || new Date().toISOString();
  const body = JSON.parse(payloadStr);
  delete body.sig;                                  // 先摘掉既有 sig 再算，避免自指
  const payloadNoSig = JSON.stringify(body);
  const input = signingInput({ ts, from_mode: seat, payload_md: payloadNoSig });
  const sig = cSign(null, Buffer.from(input, 'utf8'), privPem).toString('base64');
  return { ts, payload_md: JSON.stringify({ ...body, sig }) };
}

