args.content:
#!/usr/bin/env node
/**
 * quarantine_bak.mjs v0.1（2026-09-17 · 砚坚）
 *
 * 技能库备份目录隔离件 —— 默认干跑，绝不擅自删。
 *
 * 背景：K3 交割包安装留了 57 份 .bak-20260917-092122 备份目录（约 30 MB），
 *       与 93 件现役技能混在同一目录下，清点、审计、补全都要先跳过它们。
 * 立场：**删除不可逆，隔离可逆**。所以本件只做 mv（移入归档区），
 *       且默认 --dry-run，必须显式 --apply 才真的动，还要加 --i-mean-it 二次确认。
 *
 * 用法：
 *   node quarantine_bak.mjs                       # 干跑，只列出将做什么
 *   node quarantine_bak.mjs --apply --i-mean-it   # 真的移动（可逆：归档区仍在，可移回）
 *   node quarantine_bak.mjs --restore             # 从归档区移回（撤销）
 *
 * 归档区默认： ~/.workbuddy/skills_archive_20260917/
 */

import { readdirSync, existsSync, mkdirSync, renameSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { homedir } from 'node:os';

const SKILLS = join(homedir(), '.workbuddy', 'skills');
const ARCHIVE = join(homedir(), '.workbuddy', 'skills_archive_20260917');
const SUFFIX = '.bak-20260917-092122';

function listBackups() {
  return readdirSync(SKILLS, { withFileTypes: true })
    .filter(d => d.isDirectory() && d.name.endsWith(SUFFIX))
    .map(d => d.name);
}

function sizeKB(p) {
  let total = 0;
  const walk = (dir) => {
    for (const e of readdirSync(dir, { withFileTypes: true })) {
      const f = join(dir, e.name);
      try { if (e.isDirectory()) walk(f); else total += statSync(f).size; } catch {}
    }
  };
  try { walk(p); } catch {}
  return total / 1024;
}

function main() {
  const args = process.argv.slice(2);
  const apply = args.includes('--apply');
  const confirm = args.includes('--i-mean-it');
  const restore = args.includes('--restore');

  if (restore) {
    if (!existsSync(ARCHIVE)) return console.error('[隔离] 归档区不存在，无可撤销');
    const items = readdirSync(ARCHIVE, { withFileTypes: true }).filter(d => d.isDirectory()).map(d => d.name);
    console.log(`[隔离] 撤销：将 ${items.length} 项移回 ${SKILLS}`);
    if (!apply || !confirm) return console.log('[隔离] 干跑结束（撤销需 --apply --i-mean-it）');
    let ok = 0, fail = 0;
    for (const n of items) {
      try { renameSync(join(ARCHIVE, n), join(SKILLS, n)); ok++; } catch (e) { fail++; console.error('  失败 ' + n + '：' + e.message); }
    }
    console.log(`[隔离] 撤销完成：成功 ${ok}，失败 ${fail}`);
    return;
  }

  const baks = listBackups();
  if (!baks.length) return console.log('[隔离] 未发现待隔离备份，技能库目录已干净');

  const skills = readdirSync(SKILLS, { withFileTypes: true })
    .filter(d => d.isDirectory() && !d.name.endsWith(SUFFIX)).length;

  console.log(`=== 备份隔离件 v0.1（砚坚）===`);
  console.log(`现役技能：${skills} 件`);
  console.log(`待隔离备份：${baks.length} 份，后缀 ${SUFFIX}`);
  const sample = baks.slice(0, 3);
  console.log(`样例：${sample.join(' / ')}${baks.length > 3 ? ' …' : ''}`);
  console.log(`归档区：${ARCHIVE}`);

  if (!apply) {
    console.log('\n[干跑] 以上为将要执行的内容，未做任何改动。');
    console.log('       真的执行： node quarantine_bak.mjs --apply --i-mean-it');
    console.log('       撤销：     node quarantine_bak.mjs --restore --apply --i-mean-it');
    return;
  }
  if (!confirm) {
    console.log('\n[已拦下] 缺 --i-mean-it。删除/移动类操作要两次确认，这是刻意的。');
    return;
  }

  mkdirSync(ARCHIVE, { recursive: true });
  let ok = 0, fail = 0, movedKB = 0;
  for (const n of baks) {
    const from = join(SKILLS, n);
    const to = join(ARCHIVE, n);
    try {
      const kb = sizeKB(from);
      renameSync(from, to);
      movedKB += kb; ok++;
    } catch (e) { fail++; console.error('  失败 ' + n + '：' + e.message); }
  }
  const left = listBackups().length;
  const nowSkills = readdirSync(SKILLS, { withFileTypes: true })
    .filter(d => d.isDirectory() && !d.name.endsWith(SUFFIX)).length;
  console.log(`\n[执行] 成功 ${ok}，失败 ${fail}，移出约 ${(movedKB / 1024).toFixed(1)} MB`);
  console.log(`[核验] 技能库现目录数=${nowSkills}（应为 ${skills}），残留备份=${left}（应为 0）`);
}

main();

