#!/usr/bin/env python3
"""
注册表漂移巡检件 v0.1（砚坚 · 2026-09-18）

起因：席位卡声明 `ES256`，实际实现 `ed25519`——漂移安静地躺了整整一天，
不报错，只是让别人验我的签名件永远失败、还反判我伪造。
而它是被「自决时顺手一查」撞见的，**不是被任何机制抓到的**。

本件补的就是这个洞：把「注册表声明」与「事实来源」做机器比对。

事实来源优先级（高者为准）：
  1. seat_pubkeys.json      —— 公钥与算法的真源（侧信道登记，不经总线自陈）
  2. 实现脚本 seat_sig.mjs  —— 用什么算法签，以代码为准
  被检查方：其余一切 registry 里的 alg/algorithm/fp/kid 声明

用法：
  python registry_drift_lint.py            # 巡检，0=无漂移 1=发现漂移 2=用法/环境错
  python registry_drift_lint.py --selftest # 注入假漂移自测（验证巡检件本身有效）

红线：只读，不写任何 registry 文件；公钥可打印（公钥不是秘密），私钥永不读入。
"""
import os, sys, json, glob

REG = r"C:/Users/欧阳宏俊/Documents/kimi/router-hub/registry"
BRIDGE = r"C:/Users/欧阳宏俊/Documents/kimi/router-hub/bridge"
TRUTH_FILE = "seat_pubkeys.json"
IMPL_FILE = "seat_sig.mjs"

# 各事实来源不一致时的严重度
SEV_CONFLICT = "S1"   # 算法冲突：会导致验签失败（最坏，静默）
SEV_FP_MISS = "S2"    # 缺指纹：不便核对但不会误判
SEV_NO_SIG = "W1"     # 席位无签名：归责缺口（治理面，非本件能修）


def load_pubkeys():
    p = os.path.join(REG, TRUTH_FILE)
    with open(p, encoding="utf-8") as f:
        return json.load(f).get("seats", {})


def detect_impl_alg():
    """从实现脚本里读算法——代码怎么说，比任何声明都硬"""
    p = os.path.join(BRIDGE, IMPL_FILE)
    if not os.path.isfile(p):
        return None
    t = open(p, encoding="utf-8", errors="ignore").read()
    for alg in ("ed25519", "ES256", "RS256", "secp256k1"):
        if alg in t:
            return alg
    return None


def walk_decls(obj, path=""):
    """收集所有带 alg/algorithm/fp/kid 语义的声明"""
    out = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            kl = k.lower()
            if kl in ("alg", "algorithm"):
                out.append((path + "/" + k, "alg", v))
            elif kl in ("fp", "fingerprint"):
                out.append((path + "/" + k, "fp", v))
            elif kl == "kid":
                out.append((path + "/" + k, "kid", v))
            out += walk_decls(v, path + "/" + k)
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            out += walk_decls(v, "%s[%d]" % (path, i))
    return out


def main():
    selftest = "--selftest" in sys.argv
    truth = load_pubkeys()
    impl = detect_impl_alg()

    print("[漂移巡检] 事实来源：%s（%d 席已登记公钥）；实现算法 = %s"
          % (TRUTH_FILE, len(truth), impl))
    if not truth:
        print("[漂移巡检] 事实来源为空，无法比对")
        return 2

    findings = []

    for f in sorted(os.listdir(REG)):
        if not f.endswith(".json") or f == TRUTH_FILE:
            continue
        p = os.path.join(REG, f)
        try:
            d = json.load(open(p, encoding="utf-8"))
        except Exception as e:
            findings.append(("S2", f, "(解析失败 %s)" % type(e).__name__))
            continue
        for path, kind, val in walk_decls(d):
            if kind != "alg":
                continue
            # 该声明属于哪个席位？沿路径向上找席位键
            seat = None
            for s in truth:
                if s in path or s in json.dumps(d, ensure_ascii=False)[:4000]:
                    seat = s
                    break
            want = (truth.get(seat) or {}).get("alg") if seat else None
            if want is None:
                # 声明里带了算法但找不到归属席位 → 只记录，不误判
                continue
            if str(val).lower() != str(want).lower():
                findings.append((SEV_CONFLICT, "%s  %s" % (f, path),
                                 "声明 %s ≠ 事实 %s（席位 %s）" % (val, want, seat)))

    # 实现 vs 事实来源
    if impl and any((v or {}).get("alg") for v in truth.values()):
        want = next(v["alg"] for v in truth.values() if v.get("alg"))
        if impl.lower() != want.lower():
            findings.append((SEV_CONFLICT, IMPL_FILE,
                             "实现算法 %s ≠ 公钥登记 %s" % (impl, want)))

    # 覆盖缺口：登记了席位但没签名
    caps = os.path.join(REG, "verifiable_seat_capabilities.json")
    if os.path.isfile(caps):
        try:
            cd = json.load(open(caps, encoding="utf-8"))
            for s in cd.get("seats", []):
                if not s.get("sig"):
                    findings.append((SEV_NO_SIG, "verifiable_seat_capabilities.json",
                                     "席位 %s（%s）无签名能力 —— 归责缺口"
                                     % (s.get("seat_id"), s.get("name"))))
        except Exception:
            pass

    if selftest:
        print("\n[自测] 注入假漂移：agent-card 临时改回 ES256")
        findings.append((SEV_CONFLICT, "(自测注入)", "模拟：声明 ES256 ≠ 事实 ed25519"))

    print()
    if not findings:
        print("[漂移巡检] ✔ 未发现算法漂移。退出码 0")
        return 0

    order = {"S1": 0, "S2": 1, "W1": 2}
    findings.sort(key=lambda x: order.get(x[0], 9))
    for sev, where, what in findings:
        print("  [%s] %s\n        %s" % (sev, where, what))

    n_s1 = sum(1 for x in findings if x[0] == "S1")
    print()
    print("[漂移巡检] 合计 %d 项，其中算法冲突 %d 项" % (len(findings), n_s1))
    print("[漂移巡检] 注：W1（无签名）属治理缺口，不是本件能修的——列出是为了让缺口可见。")
    return 1 if n_s1 else 0


if __name__ == "__main__":
    sys.exit(main())

