    return any(t in pl for t in EXEMPT_PATH_PARTS)


def walk_decls(obj, path=""):
    """收集所有带 alg/algorithm/fp/kid 语义的声明（留痕豁免路径除外）"""
    out = []
    if isinstance(obj, dict):
