RE_RESERVED = re.compile(r"""['"`]([^'"`]*[?*|][^'"`]*\.(?:md|json|jsonl|txt|csv|log|yaml|yml|html))['"`]""")
RE_GLOBCTX = re.compile(r"glob|fnmatch|iglob|latest\s*\(")


def _angle_is_filename(frag: str) -> bool:
    """H2 去噪：尖括号里若含 / 空格 = :// 或 HTML 标签形态，那是模板/HTML，不是文件名。"""
    i, j = frag.find("<"), frag.rfind(">")
    if i < 0 or j < i:
        return False
    inner = frag[i:j + 1]
    if any(c in inner for c in "/ =") or "://" in inner:
        return False
    if re.match(r"<\s*/?\s*(html|div|span|td|tr|th|li|ul|ol|p|b|i|a|table|tbody|thead|button|input|style|script|svg|g|text|rect|circle|path|br|img|strong|em|small|label|select|option|form|header|footer|main|section|nav|h[1-6])\b", inner, re.I):
        return False
    return True

