ROOTS = {
    "ima_dir": "C:/Users/欧阳宏俊/Documents/kimi/router-hub/channels/ima",
    "cfg": "C:/Users/欧阳宏俊/.config/ima",
    "ws": "C:/Users/欧阳宏俊/WorkBuddy/2026-09-17-08-27-55",
    "docs": "C:/Users/欧阳宏俊/Documents",
}

def walk(base, depth=3):
    out = []
    if not os.path.isdir(base):
        return ["<NOT DIR> %s" % base]
    for root, dirs, files in os.walk(base):
        rel = os.path.relpath(root, base)
        d = 0 if rel == "." else rel.count(os.sep) + 1
        if d >= depth:
            dirs[:] = []
        for f in files:
            out.append(os.path.join(root, f))
    return out

print("=== ima 通道目录 ===")
for p in walk(ROOTS["ima_dir"], 3)[:80]:
    print("  ", p)

print("\n=== 凭据位 ~/.config/ima ===")
if os.path.isdir(ROOTS["cfg"]):
    for f in sorted(os.listdir(ROOTS["cfg"])):
        fp = os.path.join(ROOTS["cfg"], f)
        print("   %-22s %d bytes" % (f, os.path.getsize(fp)))
else:
    print("   <不存在>")

print("\n=== 截图（工作区 + 常见下载位，近 2 天）===")
import time
now = time.time()
hits = []
for base in [ROOTS["ws"], ROOTS["docs"], "C:/Users/欧阳宏俊/Downloads",
             "C:/Users/欧阳宏俊/Desktop", "C:/Users/欧阳宏俊/Pictures"]:
    if not os.path.isdir(base):
        continue
    for root, dirs, files in os.walk(base):
        if root.count(os.sep) - base.count(os.sep) > 3:
            dirs[:] = []
            continue
        for f in files:
            if f.lower().endswith((".png", ".jpg", ".jpeg")):
                fp = os.path.join(root, f)
                try:
