# -*- coding: utf-8 -*-
"""廉价变体尝试：URL-safe / 去填充 / 编码 / 附加 Bearer"""
import os, json, urllib.request, urllib.error

CFG = os.path.join(os.path.expanduser("~"), ".config", "ima")
CID = open(os.path.join(CFG, "client_id"), encoding="utf-8").read().strip()
KEY = open(os.path.join(CFG, "api_key"), encoding="utf-8").read().strip()

URL = "https://ima.qq.com/openapi/wiki/v1/get_addable_knowledge_base_list"
BODY = json.dumps({"cursor": "", "limit": 3}).encode()


def call(headers, label):
    req = urllib.request.Request(URL, data=BODY, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=25) as r:
            t = r.read().decode("utf-8", "replace")
            return "HTTP%d %s" % (r.status, t[:150])
    except urllib.error.HTTPError as e:
        t = e.read().decode("utf-8", "replace")
        try:
            j = json.loads(t)
            return "HTTP%d code=%s %s" % (e.code, j.get("code"), j.get("msg"))
        except Exception:
            return "HTTP%d %s" % (e.code, t[:120])
    except Exception as e:
        return "ERR %s" % e


base = {"Content-Type": "application/json", "ima-openapi-clientid": CID,
        "ima-openapi-ctx": "skill_version=1.1.10"}

V = [
    ("V1 URL-safe 替换 +->/ _", {**base, "ima-openapi-apikey": KEY.replace("+", "-").replace("/", "_")}),
    ("V2 去填充", {**base, "ima-openapi-apikey": KEY.rstrip("=")}),
    ("V3 + 编码为 %2B", {**base, "ima-openapi-apikey": KEY.replace("+", "%2B")}),
    ("V4 加 Bearer", {**base, "ima-openapi-apikey": KEY, "Authorization": "Bearer " + KEY}),
    ("V5 只留前 76 位", {**base, "ima-openapi-apikey": KEY[:76]}),
    ("V6 + 前补一个 A（凑 80）", {**base, "ima-openapi-apikey": "A" + KEY[:75]}),
    ("V7 换 ctx=skill_version=1.1.10（无 clientid）", {"Content-Type": "application/json",
                                                     "ima-openapi-apikey": KEY,
                                                     "ima-openapi-ctx": "skill_version=1.1.10"}),
]
for label, h in V:
    print("%-42s -> %s" % (label, call(h, label)))

