# -*- coding: utf-8 -*-
"""目录容量与持久性盘点（只读）"""
import os, ctypes, shutil, time

MAXFILES = 400000


def vol_label(drive):
    buf = ctypes.create_unicode_buffer(1024)
    fsbuf = ctypes.create_unicode_buffer(1024)
    try:
        ctypes.windll.kernel32.GetVolumeInformationW(
            ctypes.c_wchar_p(drive), buf, ctypes.sizeof(buf), None, None, None,
            fsbuf, ctypes.sizeof(fsbuf))
        return buf.value
    except Exception:
        return ""


def size_of(path, cap=MAXFILES):
    total = 0
    nfile = 0
    truncated = False
    for root, dirs, files in os.walk(path):
        for f in files:
            try:
                total += os.path.getsize(os.path.join(root, f))
            except OSError:
                pass
            nfile += 1
            if nfile > cap:
                truncated = True
                return total, nfile, truncated
        if nfile > cap:
            break
    return total, nfile, truncated


def gb(b):
    return b / (1024 ** 3)


print("=" * 74)
print("[逻辑盘容量（Python 侧复核）]")
for d in ["C:\\", "A:\\", "D:\\", "E:\\"]:
