# -*- coding: utf-8 -*-
"""
C 盘治理候选只读盘点 v2（2026-09-18）
只读：不移动、不删除、不改名。仅统计体积与风险分级。
"""
import os, sys, time, subprocess

def size_of(path, cap=None):
    """递归统计。cap 为文件数上限，None=不设上限（避免低估）。"""
    total = 0; nfiles = 0; err = 0
    stack = [path]
    while stack:
        d = stack.pop()
        try:
            with os.scandir(d) as it:
                for e in it:
                    try:
                        if e.is_dir(follow_symlinks=False):
                            stack.append(e.path)
                        else:
                            total += e.stat(follow_symlinks=False).st_size
                            nfiles += 1
                    except Exception:
                        err += 1
        except Exception:
            err += 1
        if cap and nfiles > cap:
            break
    return total, nfiles, err

def gb(b):
    return b / (1024 ** 3)

def subdirs(path, top=12):
    out = []
    try:
        with os.scandir(path) as it:
            for e in it:
                if e.is_dir(follow_symlinks=False):
                    try:
                        s, n, _ = size_of(e.path)
                        out.append((s, e.name, n))
                    except Exception:
                        out.append((0, e.name, 0))
    except Exception:
        pass
    out.sort(reverse=True)
    return out[:top]

HOME = os.path.expanduser("~")
CAND = [
    ("T1", os.environ.get("TEMP", r"C:\Windows\Temp"), "系统临时目录，可清", "低"),
    ("T2", os.path.join(HOME, "kimi-webbridge-screenshots"), "桥接截图缓存", "低"),
    ("T3", os.path.join(HOME, ".workbuddy", "logs"), "workbuddy 日志", "低"),
    ("T4", os.path.join(HOME, ".workbuddy", "traces"), "workbuddy 轨迹", "中"),
    ("T5", os.path.join(HOME, ".workbuddy", "blobs"), "workbuddy blobs（含凭据截图，需先脱敏）", "高"),
    ("T6", os.path.join(HOME, "WorkBuddy", "2026-09-17-08-27-55", "tools"), "本会话取证图（含 Key 明文图，待机主一句即清）", "高"),
    ("T7", os.path.join(HOME, "WorkBuddy"), "WorkBuddy 工作区总（含 T6）", "高"),
    ("T8", os.path.join(HOME, "Documents", "kimi", "tasks"), "kimi/tasks 主力占用", "中"),
    ("T9", os.path.join(HOME, ".workbuddy", "binaries"), "运行时，不动", "不动"),
]

print("=" * 78)
print("C 盘治理候选只读盘点  v2   时间:", time.strftime("%Y-%m-%d %H:%M:%S"))
print("=" * 78)

# 磁盘容量
try:
    import shutil
    for drv in ["C:\\", "A:\\", "D:\\", "E:\\"]:
        try:
            t, u, f = shutil.disk_usage(drv)
            print(f"[盘] {drv}  总 {gb(t):7.1f} GB | 已用 {gb(u):7.1f} GB | 剩余 {gb(f):7.1f} GB | 使用率 {u/t*100:5.1f}%")
        except Exception:
            print(f"[盘] {drv}  不可用")
except Exception as e:
    print("[盘] 查询失败", e)
print("-" * 78)

grand = 0
for tag, path, desc, risk in CAND:
    if not os.path.exists(path):
        print(f"[{tag}] {desc}\n     {path}\n     -> 不存在，跳过\n")
        continue
    t0 = time.time()
    s, n, err = size_of(path)
    dt = time.time() - t0
    if not (tag in ("T7",)):
        grand += s
    print(f"[{tag}] {desc}   风险={risk}")
    print(f"     {path}")
    print(f"     体积 {gb(s):8.2f} GB | 文件数 {n:8d} | 异常项 {err} | 耗时 {dt:.1f}s")
    print()

print("-" * 78)
p = os.path.join(HOME, "Documents", "kimi", "tasks")
if os.path.exists(p):
    print("[T8 明细] kimi/tasks 一级子目录（按体积降序，前 12）")
    for s, name, n in subdirs(p, 12):
        print(f"     {gb(s):8.2f} GB  {name}  ({n} 文件)")
    print()

print("=" * 78)
print("只读盘点结束：未移动/删除任何文件。")

