# -*- coding: utf-8 -*-
"""桌面端物理桥接探查：ima 客户端 + 各厂商 agent 本地落点。只读。"""
import os, json, subprocess, socket

HOME = r"C:\Users\欧阳宏俊"
OUT = {}

def walk_top(d, depth=2, limit=400):
    res = []
    if not os.path.isdir(d):
        return res
    for root, dirs, files in os.walk(d):
        rel = os.path.relpath(root, d)
        lvl = 0 if rel == "." else rel.count(os.sep) + 1
        if lvl > depth:
            dirs[:] = []
            continue
        for f in files[:40]:
            res.append(os.path.join(rel, f))
        if len(res) > limit:
            break
    return res[:limit]

# 1. ima 客户端在哪
ima_hits = []
for base in [os.path.join(HOME, "AppData", "Roaming"),
             os.path.join(HOME, "AppData", "Local"),
             os.path.join(HOME, "AppData", "LocalLow"),
             r"C:\Program Files", r"C:\Program Files (x86)",
             os.path.join(HOME, "OneDrive"), os.path.join(HOME, "Desktop"),
             os.path.join(HOME, "OneDrive", "Desktop")]:
    if not os.path.isdir(base):
        continue
    try:
        for n in os.listdir(base):
            low = n.lower()
            if "ima" in low or "copilot" in low or "腾讯" in n or "tencent" in low:
                ima_hits.append(os.path.join(base, n))
    except Exception as e:
        ima_hits.append("ERR %s %s" % (base, e))
OUT["ima_candidates"] = ima_hits

# 2. 常见 agent / 桥接目录
agent_dirs = {}
for n in [".coze", ".kimi", ".codebuddy", ".workbuddy", ".codearts", ".glm",
          ".cursor", ".claude", ".openai", ".config", "imo", "imo-desktop"]:
    p = os.path.join(HOME, n)
    agent_dirs[n] = {"exists": os.path.isdir(p),
                     "top": (sorted(os.listdir(p))[:30] if os.path.isdir(p) else [])}
OUT["agent_dirs"] = agent_dirs

# 3. 桌面顶层
for label, p in [("desktop", os.path.join(HOME, "Desktop")),
                 ("onedrive_desktop", os.path.join(HOME, "OneDrive", "桌面")),
                 ("onedrive_desktop2", os.path.join(HOME, "OneDrive", "Desktop"))]:
    OUT[label] = {"exists": os.path.isdir(p),
                  "top": (sorted(os.listdir(p))[:60] if os.path.isdir(p) else [])}

# 4. 进程里有没有 ima / coze / kimi
try:
    r = subprocess.run(["tasklist", "/FO", "CSV"], capture_output=True, timeout=30)
    txt = r.stdout.decode("gbk", "replace")
    keep = [l for l in txt.splitlines() if any(k in l.lower() for k in
            ["ima", "coze", "kimi", "copilot", "node", "python", "workbuddy", "codebuddy"])]
    OUT["procs"] = keep[:40]
except Exception as e:
    OUT["procs"] = "ERR %s" % e

print(json.dumps(OUT, ensure_ascii=False, indent=1))

